CREATE TABLE IF NOT EXISTS user_addresses(id BIGSERIAL PRIMARY KEY,user_id BIGINT,receiver_name VARCHAR(255),receiver_phone VARCHAR(20),address_line VARCHAR(500),district VARCHAR(100),city VARCHAR(100),is_default BOOLEAN DEFAULT FALSE,created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS vouchers(id BIGSERIAL PRIMARY KEY,code VARCHAR(50) UNIQUE,title VARCHAR(255),discount_type VARCHAR(20),discount_value NUMERIC(12,2),max_discount_amount NUMERIC(12,2),min_order_value NUMERIC(12,2),max_usages_total INT,max_usages_per_user INT,current_usage_count INT DEFAULT 0,valid_from TIMESTAMP WITH TIME ZONE,valid_to TIMESTAMP WITH TIME ZONE,status VARCHAR(20) DEFAULT 'ACTIVE');
CREATE TABLE IF NOT EXISTS voucher_usages(id BIGSERIAL PRIMARY KEY,voucher_id BIGINT,user_id BIGINT,order_id BIGINT UNIQUE,discount_amount NUMERIC(12,2));
